CREATE TABLE IF NOT EXISTS student_service_requests (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,requester_account_id VARCHAR(64) NOT NULL,kind VARCHAR(32) NOT NULL CHECK(kind IN ('attestation','transcript','duplicate','admin_correction','appeal','other')),subject VARCHAR(200) NOT NULL,details VARCHAR(4000) NOT NULL DEFAULT '',state VARCHAR(32) NOT NULL,assigned_to VARCHAR(64),decision_reason VARCHAR(2000),output_document_ref VARCHAR(500),output_sha256 VARCHAR(64),version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX IF NOT EXISTS ix_student_service_requests_institution_id ON student_service_requests(institution_id); CREATE INDEX IF NOT EXISTS ix_student_service_requests_student_id ON student_service_requests(student_id); CREATE INDEX IF NOT EXISTS ix_student_service_requests_requester_account_id ON student_service_requests(requester_account_id); CREATE INDEX IF NOT EXISTS ix_student_service_requests_state ON student_service_requests(state);
CREATE TABLE IF NOT EXISTS student_service_request_events (id VARCHAR(64) PRIMARY KEY,request_id VARCHAR(64) NOT NULL REFERENCES student_service_requests(id),actor_id VARCHAR(64) NOT NULL,event_type VARCHAR(64) NOT NULL,note VARCHAR(2000),created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX IF NOT EXISTS ix_student_service_request_events_request_id ON student_service_request_events(request_id);
